<template><Card class="s1-ui s1-compact-list"><header class="ui-header"><div><h2>{{rule?'佣金规则':'合作协议'}}</h2><p>{{rule?'规则引用协议版本；商业主数据与真实渠道资格分别判断。':'协议正文、确认事实与有效窗口按版本保存。'}}</p></div><Button v-if="writable" type="primary" :disabled="blocked" @click="editing=null;previous=null;show=true">新建{{rule?'规则':'协议'}}草稿</Button></header><DatasetSwitch :available="demoAvailable" :all="showTestData" @change="switchDataset"/><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><div class="ui-search"><label>商户<BusinessSelect v-model="targetStore" type="stores"/></label><div class="ui-actions"><Button type="primary" @click="search">查询</Button><Button @click="reset">重置</Button></div></div><Table class="s1-list-table" v-compact-table :data="records" :columns="columns" :loading="loading" no-data-text="没有符合条件的记录"><template slot="name" slot-scope="{row}"><button class="ui-link ui-primary-name" @click="detail(row.id)">{{row.payload.name||'未命名草稿'}}</button><span class="ui-meta">{{rule?row.ruleKey:row.number}} · v{{row.revision}}</span></template><template slot="store" slot-scope="{row}">{{storeNames[row.storeId]||'商户名称读取中'}}<span class="ui-meta">{{row.storeId}}</span></template><template slot="window" slot-scope="{row}">{{row.payload.startDate||'未填写'}} 至 {{row.payload.endDate||'未填写'}}</template><template slot="rate" slot-scope="{row}">{{percent(row.payload.rateBps)}}</template><template slot="state" slot-scope="{row}"><StatusTag :value="row.status"/></template><template slot="operations" slot-scope="{row}"><Button size="small" @click="detail(row.id)">详情与历史</Button></template></Table><Page class="ui-pagination" :total="total" :current="page" :page-size="size" show-total @on-change="changePage"/><CooperationForm :visible="show" :rule="rule" :record="editing" :previous="previous" :store-id="targetStore" :busy="busy" :disabled="blocked" :error="error" @save="save" @cancel="cancel" @dirty="dirty=true"/></Card></template>
<script>import page from '../page';import PageStatus from './PageStatus';import StatusTag from './StatusTag';import BusinessSelect from './BusinessSelect';import CooperationForm from './CooperationForm';import {stage1Confirm} from '../../confirm';export default {mixins:[page],components:{PageStatus,StatusTag,BusinessSelect,CooperationForm},props:{rule:Boolean},data:()=>({targetStore:'',show:false,editing:null,previous:null,storeNames:{},columns:[{title:'名称／版本',slot:'name',minWidth:210},{title:'商户',slot:'store',minWidth:210},{title:'有效期（上海）',slot:'window',minWidth:220},{title:'比例',slot:'rate',width:105},{title:'状态',slot:'state',width:110},{title:'操作',slot:'operations',width:140}]}),computed:{path(){return this.rule?'/commission-rules':'/agreements';},writable(){return this.can(this.rule?'rule.write':'agreement.write');}},mounted(){this.initializeList(['targetStore']);this.reload();},methods:{async reload(){const value=await this.load(this.path,{targetStore:this.targetStore||undefined});if(!value)return;const names={};const ids=[...new Set(this.records.map(r=>r.storeId))];if(ids.length)try{const v=await this.ui('/lookups/stores',{selected:ids.join(','),pageSize:100});v.records.forEach(r=>{names[r.id]=r.name;});}catch(_){ids.forEach(id=>{names[id]='商户名称不可读';});}if(value.records===this.records)this.storeNames=names;},search(){this.page=1;this.remember(['targetStore']);this.reload();},reset(){this.targetStore='';this.search();},changePage(value){this.page=value;this.remember(['targetStore']);this.reload();},async save(value){const {record,previous,header,payload}=value;try{const body=record?{expectedVersion:record.version,payload}:{...header,businessType:'MALL',...(previous?{predecessorId:previous.id}:{}),payload};if(!this.rule)delete body.agreementId;const result=await this.run(this.path+(record?'/'+record.id+'/draft':''),body,record?'PUT':'POST');if(result){this.show=false;this.dirty=false;await this.reload();this.detail(result.id);}}catch(_){}},cancel(){if(this.uploading)return;const close=()=>{this.show=false;this.dirty=false;};if(this.dirty)stage1Confirm({title:'放弃未保存输入？',content:'关闭表单不会保存协议或规则。已上传文件引用不会自动提交。',onOk:close});else close();}}};</script>
